// Minimal CPU simulator: fetch-decode-execute for a tiny instruction set
function runCPU(program) {
  const mem = [...program];  // memory (array of instructions)
  const reg = { A: 0, B: 0 }; // two registers
  let pc = 0;                  // program counter

  while (pc < mem.length) {
    const instr = mem[pc++]; // FETCH (and increment PC)

    // DECODE + EXECUTE
    const [op, arg] = instr.split(' ');
    if      (op === 'LOAD_A') reg.A = Number(arg);
    else if (op === 'LOAD_B') reg.B = Number(arg);
    else if (op === 'ADD')    reg.A = reg.A + reg.B;
    else if (op === 'PRINT')  console.log('A =', reg.A);
    else if (op === 'HALT')   break;
  }
}

runCPU([
  'LOAD_A 5',
  'LOAD_B 3',
  'ADD',
  'PRINT',   // A = 8
  'HALT'
]);

